import React from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  spring,
  interpolate,
  interpolateColors,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadMontserrat = makeLoadFont('Montserrat');

// Module-level font loading
const { fontFamily: montserratFamily } = loadMontserrat();

// Highly precise width map for Montserrat ExtraBold (800 weight) Uppercase
const MONTSERRAT_EXTRABOLD_WIDTHS: Record<string, number> = {
  A: 0.77, B: 0.73, C: 0.76, D: 0.79, E: 0.68,
  F: 0.65, G: 0.81, H: 0.81, I: 0.35, J: 0.58,
  K: 0.77, L: 0.62, M: 0.98, N: 0.81, O: 0.85,
  P: 0.73, Q: 0.85, R: 0.76, S: 0.68, T: 0.67,
  U: 0.78, V: 0.73, W: 1.05, X: 0.74, Y: 0.67,
  Z: 0.71, ' ': 0.28, '-': 0.35, '.': 0.28, ',': 0.28
};

// Utility for precise typography spacing estimation
const getCharWidth = (char: string): number => {
  const upper = char.toUpperCase();
  return MONTSERRAT_EXTRABOLD_WIDTHS[upper] ?? 0.65;
};

const estimateWidthEm = (text: string): number => {
  let w = 0;
  for (let i = 0; i < text.length; i++) {
    w += getCharWidth(text[i]);
  }
  return w;
};



export type KineticTypographyProps = Record<string, any>;

const KineticTypography: React.FC<KineticTypographyProps> = ({
  backgroundColor = "#0a0a0a",
  transparentBackground = false,
  durationInSeconds = 5,

  abbreviation = "ROI",
  fullPhrase = "RETURN ON INVESTMENT",

  fontSize = 120,
  abbreviationColor = "#ffffff",
  fullPhraseColor = "#a0a0a0",
  fadeFromBlack = false,

  abbreviationLetterSpacing = 0,

  // Default to positive spacing to strictly prevent overlaps 
  abbreviationTracking = 20, 
  wordSpacing = 20,
  
  abbreviationSpacingOffsets = [],
  wordSpacingOffsets = [],

  fullPhraseTracking = 0,
  fullPhraseOffsetX = 0,
  fullPhraseOffsetY = 0,

  holdDurationFrames = 30,
  staggerFrames = 8,

  overshootIntensity = 40,

  revealMotionType = "fade",
  motionDistance = 50,
  // Force strict masking during animation to prevent visual bleed/overlap
  preventClipping = false, 
  // Increased slightly to accommodate masking bounds safely
  widthCorrectionEm = 0.4, 

  enableMotionBlur = true,
  glowIntensity = 0,
}) => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();

  // Parse background logic
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Derive layout data - Enforcing uppercase for precise measurement and visual consistency
  const safeAbbreviation = abbreviation.toUpperCase();
  const safeFullPhrase = fullPhrase.toUpperCase();

  const chars = safeAbbreviation.replace(/\s/g, "").split("");
  const words = safeFullPhrase.split(" ").filter((w) => w.trim().length > 0);
  const maxLength = Math.max(chars.length, words.length);

  const pairs = Array.from({ length: maxLength }).map((_, i) => {
    const char = chars[i] || "";
    const word = words[i] || "";

    let anchor = char;
    let rest = "";

    if (char && word) {
      rest = word.substring(1);
    } else if (char && !word) {
      anchor = char;
      rest = "";
    } else if (!char && word) {
      anchor = word.charAt(0);
      rest = word.substring(1);
    }

    return { anchor, rest };
  });

  // Calculate Spring Physics Based on Overshoot Slider
  const damping = interpolate(overshootIntensity, [0, 100], [20, 8]);
  const stiffness = interpolate(overshootIntensity, [0, 100], [100, 140]);

  // Global progress dictates the tracking/spacing between word blocks
  const globalProgress = spring({
    frame: frame - holdDurationFrames,
    fps,
    config: { damping, stiffness },
  });

  // Cinematic slow scale over the entire duration
  const cinematicScale = interpolate(
    frame,
    [0, fps * durationInSeconds],
    [1, 1.08],
    { extrapolateRight: "clamp" }
  );

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        fontFamily: montserratFamily,
        justifyContent: "center",
        alignItems: "center",
        transition: "none",
      }}
    >
      <div
        style={{
          display: "flex",
          flexDirection: "row",
          justifyContent: "center",
          alignItems: "center",
          transform: `scale(${cinematicScale})`,
          transition: "none",
          textAlign: "center", // Explicitly ensure composition text is centered
        }}
      >
        {pairs.map((pair, i) => {
          const delay = holdDurationFrames + i * staggerFrames;
          const itemProgress = spring({
            frame: frame - delay,
            fps,
            config: { damping, stiffness },
          });

          // Individualized gap adjustments
          const customAbbrOffset = abbreviationSpacingOffsets[i] ?? 0;
          const customWordOffset = wordSpacingOffsets[i] ?? 0;
          const itemGap = interpolate(
            globalProgress,
            [0, 1],
            [abbreviationTracking + customAbbrOffset, wordSpacing + customWordOffset]
          );

          // Compute exact width for perfect spacing when in full phrase, accommodating phrase tracking
          const trackingWidthEm = pair.rest ? (fullPhraseTracking * pair.rest.length) / fontSize : 0;
          const baseWidth = Math.max(0, estimateWidthEm(pair.rest) + trackingWidthEm);
          const targetWidthEm = baseWidth > 0 ? baseWidth + widthCorrectionEm : 0;
          const currentWidthEm = itemProgress * targetWidthEm;
          const safeWidthEm = Math.max(0, currentWidthEm);

          // Fade & Motion Blur computations
          const opacityValue = interpolate(itemProgress, [0, 0.6], [0, 1], {
            extrapolateLeft: "clamp",
            extrapolateRight: "clamp",
          });

          const blurValue = enableMotionBlur
            ? interpolate(itemProgress, [0, 0.5, 1], [0, 8, 0], {
                extrapolateLeft: "clamp",
                extrapolateRight: "clamp",
              })
            : 0;
            
          const clampedProgress = Math.max(0, Math.min(1, itemProgress));
          const currentTextColor = fadeFromBlack
            ? interpolateColors(clampedProgress, [0, 1], ["#000000", fullPhraseColor])
            : fullPhraseColor;

          // Motion Reveal computations
          const distanceEm = motionDistance / 100;
          const slideOutEm = interpolate(itemProgress, [0, 1], [-distanceEm, 0], {
            extrapolateLeft: "clamp",
            extrapolateRight: "clamp",
          });
          const slideUpEm = interpolate(itemProgress, [0, 1], [distanceEm, 0], {
            extrapolateLeft: "clamp",
            extrapolateRight: "clamp",
          });
          const scaleValue = interpolate(itemProgress, [0, 1], [1 - (distanceEm / 2), 1], {
            extrapolateLeft: "clamp",
            extrapolateRight: "clamp",
          });

          let tx = 0;
          let ty = 0;
          let sc = 1;

          if (revealMotionType === "slide-right") tx = slideOutEm;
          if (revealMotionType === "slide-up") ty = slideUpEm;
          if (revealMotionType === "scale") sc = scaleValue;

          // Shadow depth formatting
          const abbreviationShadow =
            glowIntensity > 0
              ? `0 0 ${glowIntensity}px ${abbreviationColor}, 0 0 ${glowIntensity * 2}px ${abbreviationColor}`
              : undefined;

          const phraseShadow =
            glowIntensity > 0
              ? `0 0 ${glowIntensity}px ${currentTextColor}, 0 0 ${glowIntensity * 2}px ${currentTextColor}`
              : undefined;

          return (
            <div
              key={i}
              style={{
                display: "flex",
                flexDirection: "row",
                alignItems: "center",
                transition: "none",
                position: "relative",
                zIndex: pairs.length - i, // Ensures correct overlap ordering
                marginRight: i < pairs.length - 1 ? `${itemGap}px` : 0,
              }}
            >
              {/* Anchor Character */}
              <div
                style={{
                  color: abbreviationColor,
                  fontSize: `${fontSize}px`,
                  fontWeight: 800,
                  lineHeight: 1.1, // Fixed alignment baseline 
                  padding: "0.5em 0", // Matched with emerging text to prevent vertical offset
                  marginTop: "-0.5em",
                  marginBottom: "-0.5em",
                  textShadow: abbreviationShadow,
                  zIndex: 2,
                  transition: "none",
                  letterSpacing: `${abbreviationLetterSpacing}px`,
                }}
              >
                {pair.anchor}
              </div>

              {/* Emerging Associated Word */}
              <div
                style={{
                  width: `${safeWidthEm}em`,
                  transform: `translate(${fullPhraseOffsetX}px, ${fullPhraseOffsetY}px)`,
                  opacity: opacityValue,
                  overflow: preventClipping ? "visible" : "hidden",
                  whiteSpace: "nowrap",
                  color: currentTextColor,
                  fontSize: `${fontSize}px`,
                  fontWeight: 800,
                  lineHeight: 1.1, // Fixed alignment baseline
                  textShadow: phraseShadow,
                  filter: blurValue > 0 ? `blur(${blurValue}px)` : "none",
                  padding: "0.5em 0", 
                  marginTop: "-0.5em", 
                  marginBottom: "-0.5em",
                  marginLeft: 0,
                  // Negating the explicit correction width on the right margin ensures the entire 
                  // flex layout perfectly centers visually without accumulated blank space.
                  marginRight: pair.rest ? `-${itemProgress * widthCorrectionEm}em` : 0,
                  display: "flex",
                  alignItems: "center",
                  zIndex: 1,
                  letterSpacing: `${fullPhraseTracking}px`,
                  transition: "none",
                }}
              >
                <span
                  style={{
                    display: "inline-block",
                    transform: `translate(${tx}em, ${ty}em) scale(${sc})`,
                    transformOrigin: "left center",
                    transition: "none",
                  }}
                >
                  {pair.rest}
                </span>
              </div>
            </div>
          );
        })}
      </div>
    </AbsoluteFill>
  );
};

export default KineticTypography;